// =============================================================================
// VerseData.js
// -----------------------------------------------------------------------------
// A Scriptable data module for the "Daily Verse" widget.
//
// This file holds 365 entries, one per calendar day of the year (index 0 = Jan 1,
// index 364 = Dec 31). The main script picks today's entry by day-of-year, so
// this module works completely offline and never repeats within a year.
//
// Each entry has the shape:
//   {
//     reference:  "Psalm 23:1"          -- the specific verse shown on the widget
//     passage:    "Psalm 23:1-6"        -- the surrounding passage for context
//     theme:      "Provision"           -- one or two words
//     context:    "..."                 -- 1-2 sentences: who is speaking, to
//                                           whom, and what is happening
//     reflection: "...?"                -- one short reflective question
//     text:       ""                    -- INTENTIONALLY BLANK. Paste your own
//                                           NIV 1984 verse text here on your
//                                           laptop; it will sync via iCloud
//                                           Drive. See "Daily Verse.js" for how
//                                           missing text is handled (optional
//                                           API fetch + cache, or a fallback
//                                           note).
//   }
//
// Edit this file on your laptop (in iCloud Drive/Scriptable) to fill in `text`
// for each day. Do not change `reference`/`passage` unless you also update the
// corresponding `text` you paste in.
// =============================================================================

